import{_ as s,o as i,c as t,a2 as a}from"./chunks/framework.DGp-bpT-.js";const c=JSON.parse('{"title":"Time Messenger Integration Setup","description":"Connect SREBot to Time Messenger: create a bot, obtain a token and channel ID, and configure Helm.","frontmatter":{"title":"Time Messenger Integration Setup","description":"Connect SREBot to Time Messenger: create a bot, obtain a token and channel ID, and configure Helm.","head":[["link",{"rel":"canonical","href":"https://srebot.site360.tech/docs/en/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"ru","href":"https://srebot.site360.tech/docs/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"en","href":"https://srebot.site360.tech/docs/en/guide/time-setup.md"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://srebot.site360.tech/docs/guide/time-setup.md"}]]},"headers":[],"relativePath":"en/guide/time-setup.md","filePath":"en/guide/time-setup.md","lastUpdated":1785140323000}'),n={name:"en/guide/time-setup.md"};function l(h,e,o,p,r,d){return i(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="time-messenger-integration-setup" tabindex="-1">Time Messenger Integration Setup <a class="header-anchor" href="#time-messenger-integration-setup" aria-label="Permalink to &quot;Time Messenger Integration Setup&quot;">​</a></h1><p>SREBot supports the corporate messenger <a href="https://time-messenger.ru/" target="_blank" rel="noreferrer">Time</a> alongside Telegram, Slack, and Discord. The bot reads Alertmanager notifications in a selected channel, starts an RCA, and replies in the incident thread.</p><p>The integration uses Time API v4: new posts arrive over an authenticated WebSocket connection, while replies and message edits use the REST API.</p><h2 id="_1-create-a-bot-in-time" tabindex="-1">1. Create a Bot in Time <a class="header-anchor" href="#_1-create-a-bot-in-time" aria-label="Permalink to &quot;1. Create a Bot in Time&quot;">​</a></h2><p>Bot account creation must be enabled in your Time workspace.</p><ol><li>Open the main Time menu and select <strong>Integrations</strong>.</li><li>Go to <strong>Bot Accounts</strong> and click <strong>Add Bot Account</strong>.</li><li>Set the bot&#39;s name, username, and optionally its avatar.</li><li>Copy the token shown after the bot is created.</li></ol><div class="danger custom-block"><p class="custom-block-title">Save the token</p><p>Time displays the bot token only once. Store it as a secret and never commit it to Git.</p></div><p>See Time&#39;s official <a href="https://docs.time-messenger.ru/api/cookbook/create-a-bot/" target="_blank" rel="noreferrer">bot creation guide</a> for more detail.</p><h2 id="_2-add-the-bot-to-the-channel" tabindex="-1">2. Add the Bot to the Channel <a class="header-anchor" href="#_2-add-the-bot-to-the-channel" aria-label="Permalink to &quot;2. Add the Bot to the Channel&quot;">​</a></h2><p>Add the new bot to the channel where Alertmanager posts notifications. The bot account must be able to:</p><ul><li>read channel posts;</li><li>publish posts and thread replies;</li><li>edit and delete its own posts.</li></ul><p>Record the channel&#39;s string ID for <code>TIME_CHANNEL_ID</code>. Obtain it through the Time API or from your workspace administrator. Do not use the channel display name in place of its ID.</p><h2 id="_3-verify-the-token" tabindex="-1">3. Verify the Token <a class="header-anchor" href="#_3-verify-the-token" aria-label="Permalink to &quot;3. Verify the Token&quot;">​</a></h2><p>Verify the Time base URL and token with an API request:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail-with-body</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer &lt;TIME_TOKEN&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;https://time.example.com/api/v4/users/me&quot;</span></span></code></pre></div><p>The response should describe the bot account. <code>TIME_BASE_URL</code> must contain only the server&#39;s base address, without the <code>/api/v4</code> suffix.</p><h2 id="_4-configure-srebot" tabindex="-1">4. Configure SREBot <a class="header-anchor" href="#_4-configure-srebot" aria-label="Permalink to &quot;4. Configure SREBot&quot;">​</a></h2><p>For Docker Compose or an <code>.env</code> deployment, set:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://time.example.com</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-Time-bot-token</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">TIME_CHANNEL_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-Time-channel-id</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SAAS_AGENT_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">replace-with-SREBot-agent-token</span></span></code></pre></div><p>For Helm, add the credentials to <code>values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_base_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://time.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-bot-token&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  time_channel_id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-channel-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  saas_agent_token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-SREBot-agent-token&quot;</span></span></code></pre></div><p>For production and GitOps, create a Kubernetes Secret in advance:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">apiVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">kind</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">metadata</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">srebot-secret</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Opaque</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stringData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_BASE_URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://time.example.com&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-bot-token&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  TIME_CHANNEL_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-Time-channel-id&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  SAAS_AGENT_TOKEN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;replace-with-SREBot-agent-token&quot;</span></span></code></pre></div><p>Then reference it from <code>values.yaml</code>:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">secrets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  existingSecret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;srebot-secret&quot;</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Only one chat integration</p><p>One SREBot process can use only one chat platform. When selecting Time, leave the Telegram, Slack, and Discord credentials empty or the bot will stop during startup with a configuration error.</p></div><h2 id="_5-verify-the-integration" tabindex="-1">5. Verify the Integration <a class="header-anchor" href="#_5-verify-the-integration" aria-label="Permalink to &quot;5. Verify the Integration&quot;">​</a></h2><p>After startup, the logs should indicate that the <code>time</code> integration was selected, the WebSocket connected, and the bot is listening to the configured channel. Send a test alert to that channel.</p><p>SREBot creates a separate thread for every alert group. Follow-up questions and the <code>mute</code>, <code>unmute</code>, and <code>status</code> commands work inside these threads. Start a general diagnostic query by directly mentioning the bot&#39;s <code>@username</code>.</p><p>If the bot does not respond, verify:</p><ul><li>SREBot can reach <code>TIME_BASE_URL</code> over HTTPS and WebSocket;</li><li>the bot belongs to the channel identified by <code>TIME_CHANNEL_ID</code>;</li><li>the account can read the channel and post messages;</li><li>the token belongs to the bot account and has not been revoked;</li><li>no other chat integration is configured at the same time.</li></ul>`,31)])])}const g=s(n,[["render",l]]);export{c as __pageData,g as default};
